def reclassificar_acessorios(apps, schema_editor):
    """Corrige promoções que a regra antiga jogava na categoria errada:
    capa/case/película/suporte/volante/dock/carregador (→ acessorio), cabos
    vendidos para console (→ cabo) e periféricos que viravam jogo só por
    terminarem em 'PS5'/'Xbox' (ex.: 'Joy-Con Nintendo Switch', 'Teclado para
    PS5'). Jogos de verdade continuam em 'jogo'."""
    from bot.classifier import detectar_categoria
    from bot.services import _linha_titulo

    Promo = apps.get_model('bot', 'Promo')
    acessorios = 0
    cabos = 0
    jogos_corrigidos = 0
    qs = Promo.objects.exclude(categoria__in=['acessorio', 'cupom'])
    for promo in qs.iterator():
        texto = promo.texto_original or promo.titulo or ''
        if not texto:
            continue
        titulo = promo.titulo or _linha_titulo(texto)
        try:
            correta = detectar_categoria(texto, titulo=titulo)
        except Exception:
            continue
        if correta == 'acessorio' and promo.categoria != 'acessorio':
            promo.categoria = 'acessorio'
            promo.save(update_fields=['categoria'])
            acessorios += 1
        elif correta == 'cabo' and promo.categoria in ('console', 'controle'):
            promo.categoria = 'cabo'
            promo.save(update_fields=['categoria'])
            cabos += 1
        elif (
            promo.categoria == 'jogo'
            and correta in _CATEGORIAS_CORRIGIVEIS
            and correta != 'jogo'
        ):
            promo.categoria = correta
            promo.save(update_fields=['categoria'])
            jogos_corrigidos += 1

    if acessorios:
        print(f'Acessórios reclassificados: {acessorios}')
    if cabos:
        print(f'Cabos reclassificados de console/controle para cabo: {cabos}')
    if jogos_corrigidos:
        print(f'Periféricos reclassificados de jogo: {jogos_corrigidos}')


